import { I, dish } from "./catalog-kit";
import type { Recipe } from "./types";

function so(
  id: string,
  name: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  aliases: string[] = [],
  nutrition?: Recipe["nutrition"],
  extra?: Partial<Pick<Recipe, "servings" | "photo">>,
): Recipe {
  return dish({
    id,
    name,
    description,
    minutes,
    protein,
    plate,
    cuisine: "Southern",
    tags: Array.from(new Set(["southern", ...tags])),
    aliases,
    ingredients,
    steps,
    nutrition,
    photo: extra?.photo ?? `/food/${id}.jpg`,
    ...(extra?.servings ? { servings: extra.servings } : {}),
  });
}

